{

"kind": "propose",
"summary": "Log-shipper's CPU limit is insufficient, causing buffer full and blocking renderer. Raise log-shipper's CPU limit to resolve the issue.",
"hypotheses": [
  {
    "root_cause_class": "other",
    "summary": "Renderer is blocked by log-shipper due to CPU-starvation (ev-container_logs_tail, ev-target_events), not its own CPU limit.",
    "supporting": ["ev-container_logs_tail", "ev-target_events"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Log-shipper's CPU limit of 100m is too low for its usage (0.012 cores) and blocks renderer.",
    "supporting": ["ev-container_cpu"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "log-shipper": {
        "limits": {
          "cpu": "200m"
        }
      }
    }
  },
  "expected_effect": "Raise log-shipper's CPU limit from 100m to 200m to prevent buffer full and block renderer (ev-container_logs_tail, ev-target_events).",
  "rationale": "Renderer is waiting on log-shipper due to CPU-starvation (ev-container_logs_tail) and the event explicitly advises raising log-shipper's CPU limit (ev-target_events). The log-shipper's current limit of 100m is insufficient for its usage (0.012 cores) and causes blocking. Increasing its limit to 200m addresses the root cause without affecting renderer's resources.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-target_events", "ev-container_cpu"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
